def _sd(s:str)->str:return s if s.isascii() else ''.join(c for c in unicodedata.normalize('NFKD',s) if not unicodedata.combining(c)).replace('đ','d').replace('Đ','D')
def _gc(d:dict,b:bool)->tuple:return (re.compile((r"(?<!\w)(?:" if b else "(?:")+"|".join(map(re.escape,sorted(d,key=len,reverse=True)))+(r")(?!\w)" if b else ")")),lambda m:' '+d[m.group(0)].upper()+' ')
GLD={g:{(k if g=='vi' else _sd(k)):v for k,v in (x.split('=',1) for x in s.split(';'))} for g,s in GLS.items()}
