FP1=re.compile(r"\b(?:i|im|ive|id|ill|me|myself)\b");OTHS=re.compile(r"\b(?:he|she|they|hes|shes|theyre|him|her|them|my (?:\w+ )?(?:friend|brother|sister|son|daughter|mom|dad|husband|wife|partner|boyfriend|girlfriend|roommate|cousin|kid|classmate))\b");SLFS=re.compile(r"\b(?:im|i am|myself|i want|i feel|i cant|i have|i dont|i wish|i will|ill)\b")
