TRAF="If someone is controlling where you go or taking your documents, the US National Human Trafficking Hotline is 1-888-373-7888 (or text 233733)."
DV="When you're safe, the US National Domestic Violence Hotline is 1-800-799-7233 (or text START to 88788)."
BND=re.compile(r" (?:\.|,) | but | although | though | however ")
MULTI=re.compile(r"\b(?:parents|grandparents|both|(?:mom|mommy|mother|dad|daddy|father|grandma|grandpa) and (?:my )?(?:mom|mommy|mother|dad|daddy|father|grandma|grandpa)|two people|three people|everyone|everybody|my family|whole family|(?:they|theyre|them) (?:are )?(?:both|all))\b")
DOM=re.compile(r"\b(?:husband|wife|boyfriend|girlfriend|partner|ex|fiance|fiancee|dad|mom|stepdad|stepmom|father|mother|brother|sister|son|uncle|spouse|family|home)\b")
